        let c = parse_path_d("M0 0 L10 0 L10 10 Z m 20 0 h5 v5 z");
        assert_eq!(c.len(), 2);
        assert_eq!(c[0].len(), 4);
    }
    #[test]
    fn svg_shapes() {
        let c = parse_svg("<svg><rect x='1' y='1' width='2' height='3'/><circle cx=\"5\" cy=\"5\" r=\"1\"/></svg>");
        assert_eq!(c.len(), 2);
    }
    #[test]
    fn text_has_outlines() {
        assert!(!text_contours("Hi").is_empty());
    }
}

