    let mut out: Vec<Contour> = Vec::new();
    let mut cur: Contour = Vec::new();
    let mut pen = Pos2::ZERO;
    let mut start = Pos2::ZERO;
    let mut last_ctrl: Option<Pos2> = None;
    let mut cmd = 'M';
    let mut k = 0;
    let num = |k: &mut usize| -> Option<f32> {
        if let Some(Tok::Num(v)) = toks.get(*k) {
            *k += 1;
            Some(*v)
