        assert_eq!(p.len(), 18);
        assert_eq!(&p[..2], &[0xF1, 0x17]);
    }
    #[test]
    fn mac() {
        assert_eq!(parse_mac(DEFAULT_MAC), Some([0x00, 0x06, 0x66, 0x8D, 0x2B, 0xFE]));
    }
}

