                    let (r, _) = ui.allocate_exact_size(vec2(28.0, 28.0), Sense::hover());
                    ui.painter().circle_filled(r.center(), 13.0, ACCENT);
                    ui.painter().line_segment(
                        [r.center() + vec2(-6.0, 5.0), r.center() + vec2(6.0, -5.0)],
                        Stroke::new(2.5, Color32::WHITE),
                    );
                    ui.label(RichText::new("MatCraft").color(Color32::WHITE).size(18.0).strong());
                    ui.add_space(16.0);
                    let title = match self.screen {
                        Screen::Design => "Canvas",
                        Screen::Make => "Prepare",
                    };
                    ui.label(RichText::new(title).color(Color32::from_gray(190)).size(15.0));
                    ui.label(RichText::new("·").color(Color32::from_gray(120)));
                    ui.add(
                        egui::TextEdit::singleline(&mut self.project_name)
                            .desired_width(160.0)
                            .text_color(Color32::WHITE)
                            .background_color(Color32::from_rgb(0x2e, 0x3a, 0x42))
                            .frame(egui::Frame::NONE),
                    );
                    ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                        match self.screen {
                            Screen::Design => {
                                if green_button(ui, "Make it").clicked() {
                                    self.screen = Screen::Make;
                                    self.mat_index = 0;
                                }
                            }
                            Screen::Make => {
                                if ui
                                    .add(
                                        egui::Button::new(RichText::new("Back to canvas").color(Color32::WHITE))
                                            .fill(Color32::from_rgb(0x3a, 0x48, 0x52))
                                            .corner_radius(CornerRadius::same(18)),
                                    )
                                    .clicked()
                                {
                                    self.screen = Screen::Design;
                                }
                            }
                        }
                        ui.add_space(12.0);
                        let (dot, txt) = match &self.connected {
                            Some(n) => (ACCENT, format!("Machine: {n}")),
