                                .corner_radius(CornerRadius::same(14)),
                        );
                        let c = resp.rect.left_center() + vec2(-8.0, 0.0);
                        ui.painter().circle_filled(c, 5.0, dot);
                        if resp.clicked() {
                            self.show_machine = !self.show_machine;
                        }
