    fn canvas(&mut self, ui: &mut Ui) {
        let (rect, resp) = ui.allocate_exact_size(ui.available_size(), Sense::click_and_drag());
        let painter = ui.painter_at(rect);
        let ppi = BASE_PPI * self.zoom;
        let origin = rect.min + self.pan;
        let to_screen = |p: Pos2| origin + p.to_vec2() * ppi;
        let to_world = |s: Pos2| ((s - origin) / ppi).to_pos2();

        // grid: 1-inch lines, darker every 6 inches, numbers along the top and left
        painter.rect_filled(rect, 0.0, CANVAS_BG);
        let w0 = to_world(rect.min);
        let w1 = to_world(rect.max);
        let mut x = w0.x.floor();
        while x <= w1.x {
            let sx = to_screen(pos2(x, 0.0)).x;
            let strong = (x as i32) % 6 == 0;
            painter.line_segment(
                [pos2(sx, rect.top()), pos2(sx, rect.bottom())],
                Stroke::new(1.0, if strong { Color32::from_gray(203) } else { Color32::from_gray(226) }),
            );
            if x >= 0.0 {
                painter.text(pos2(sx + 3.0, rect.top() + 2.0), Align2::LEFT_TOP, format!("{}", x as i32), FontId::proportional(10.0), MUTED);
            }
            x += 1.0;
        }
        let mut y = w0.y.floor();
        while y <= w1.y {
            let sy = to_screen(pos2(0.0, y)).y;
            let strong = (y as i32) % 6 == 0;
            painter.line_segment(
                [pos2(rect.left(), sy), pos2(rect.right(), sy)],
                Stroke::new(1.0, if strong { Color32::from_gray(203) } else { Color32::from_gray(226) }),
            );
            if y > 0.0 {
                painter.text(pos2(rect.left() + 3.0, sy + 2.0), Align2::LEFT_TOP, format!("{}", y as i32), FontId::proportional(10.0), MUTED);
            }
            y += 1.0;
        }
        // the 12 x 12 inch cutting area
        let area = Rect::from_min_max(to_screen(Pos2::ZERO), to_screen(pos2(12.0, 12.0)));
        painter.rect_stroke(area, 0.0, Stroke::new(1.5, Color32::from_gray(170)), StrokeKind::Middle);

        for it in self.items.iter().filter(|i| i.visible) {
            draw_item(&painter, it, &to_screen, Vec2::ZERO, None);
        }

        // selection box and its four corner buttons: delete, rotate, resize, lock
        let mut handles: Option<[Pos2; 4]> = None;
        if let Some(s) = self.selected.filter(|s| *s < self.items.len()) {
            let it = &self.items[s];
            let corners = [pos2(0., 0.), pos2(1., 0.), pos2(1., 1.), pos2(0., 1.), pos2(0., 0.)].map(|u| to_screen(it.to_world(u)));
            painter.add(Shape::line(corners.to_vec(), Stroke::new(1.5, SELECT)));
            let hs = [corners[0], corners[1], corners[2], corners[3]];
            for (n, p) in hs.iter().enumerate() {
                let col = if n == 0 { Color32::from_rgb(0xd9, 0x4b, 0x4b) } else { SELECT };
                painter.circle_filled(*p, 11.0, Color32::WHITE);
                painter.circle_stroke(*p, 11.0, Stroke::new(1.2, col));
                let st = Stroke::new(1.6, col);
                match n {
                    0 => {
                        painter.line_segment([*p + vec2(-4.0, -4.0), *p + vec2(4.0, 4.0)], st);
                        painter.line_segment([*p + vec2(-4.0, 4.0), *p + vec2(4.0, -4.0)], st);
                    }
                    1 => {
                        let arc: Vec<Pos2> = (0..=12)
                            .map(|k| {
                                let a = -2.6 + k as f32 * 0.42;
                                *p + vec2(a.cos(), a.sin()) * 5.0
                            })
                            .collect();
                        painter.add(Shape::line(arc, st));
                    }
                    2 => {
                        painter.line_segment([*p + vec2(-4.5, -4.5), *p + vec2(4.5, 4.5)], st);
                        painter.line_segment([*p + vec2(4.5, 4.5), *p + vec2(0.5, 4.5)], st);
                        painter.line_segment([*p + vec2(4.5, 4.5), *p + vec2(4.5, 0.5)], st);
                    }
                    _ => {
                        painter.rect_stroke(Rect::from_center_size(*p + vec2(0.0, 1.5), vec2(8.0, 6.0)), 1.0, st, StrokeKind::Middle);
                        if self.lock_aspect {
                            painter.circle_stroke(*p + vec2(0.0, -2.5), 2.8, st);
                        }
                    }
                }
            }
            painter.text(
                to_screen(it.to_world(pos2(0.5, 1.0))) + vec2(0.0, 20.0),
                Align2::CENTER_CENTER,
                format!("{:.2} in x {:.2} in", it.size[0], it.size[1]),
                FontId::proportional(11.0),
                SELECT,
            );
            handles = Some(hs);
        }

        // zoom with the wheel, around the pointer
        if resp.hovered() {
            let scroll = ui.input(|i| i.smooth_scroll_delta.y);
            if scroll != 0.0 {
                if let Some(mp) = ui.input(|i| i.pointer.hover_pos()) {
                    let before = to_world(mp);
                    self.zoom = (self.zoom * (1.0 + scroll * 0.0015)).clamp(0.25, 6.0);
                    self.pan = mp - rect.min - before.to_vec2() * (BASE_PPI * self.zoom);
                }
            }
        }

        let pointer = resp.interact_pointer_pos();
        let near = |b: Pos2| pointer.map(|a| (a - b).length() < 13.0).unwrap_or(false);

        if resp.clicked() {
            if let Some([del, _, _, lock]) = handles {
                if near(del) {
                    self.delete_selected();
                    return;
                }
                if near(lock) {
                    self.lock_aspect = !self.lock_aspect;
                    return;
                }
            }
            if let Some(p) = pointer {
                let w = to_world(p);
                self.selected = (0..self.items.len()).rev().find(|&i| {
                    let it = &self.items[i];
                    let u = it.from_world(w);
                    it.visible && (-0.05..=1.05).contains(&u.x) && (-0.05..=1.05).contains(&u.y)
                });
            }
        }

        if resp.drag_started() {
            let p = pointer.unwrap_or_default();
            let pan_mode = ui.input(|i| i.pointer.middle_down() || i.key_down(Key::Space));
            self.drag = Drag::None;
            if pan_mode {
                self.drag = Drag::Pan;
            } else if let Some([_, rot, size, _]) = handles {
                if near(rot) {
                    self.drag = Drag::Rotate;
                } else if near(size) {
                    self.drag = Drag::Resize;
                }
            }
            if self.drag == Drag::None {
                let w = to_world(p);
                let hit = (0..self.items.len()).rev().find(|&i| {
                    let it = &self.items[i];
                    let u = it.from_world(w);
                    it.visible && (-0.05..=1.05).contains(&u.x) && (-0.05..=1.05).contains(&u.y)
                });
                match hit {
                    Some(i) => {
                        self.selected = Some(i);
                        self.drag = Drag::Move;
                    }
                    None => self.drag = Drag::Pan,
                }
            }
            if matches!(self.drag, Drag::Move | Drag::Resize | Drag::Rotate) {
                self.snapshot();
                self.drag_item = self.selected.map(|s| self.items[s].clone());
            }
            self.drag_start = p;
        }

        if resp.dragged() {
            let delta = resp.drag_delta();
            match self.drag {
                Drag::Pan => self.pan += delta,
                Drag::Move => {
                    if let Some(s) = self.selected {
                        self.items[s].pos[0] += delta.x / ppi;
                        self.items[s].pos[1] += delta.y / ppi;
                    }
                }
                Drag::Resize => {
                    if let (Some(s), Some(orig), Some(p)) = (self.selected, self.drag_item.clone(), pointer) {
                        // keep the top-left corner where it is and stretch toward the pointer
                        let anchor = orig.to_world(pos2(0.0, 0.0));
                        let d = to_world(p) - anchor;
                        let (sn, co) = (-orig.rot).to_radians().sin_cos();
                        let local = vec2(d.x * co - d.y * sn, d.x * sn + d.y * co);
                        let mut nw = local.x.max(0.1);
                        let thin = orig.size[1] < 0.001;
                        let mut nh = if thin { orig.size[1] } else { local.y.max(0.1) };
                        if self.lock_aspect && !thin {
                            let k = (nw / orig.size[0]).max(nh / orig.size[1]);
                            nw = orig.size[0] * k;
                            nh = orig.size[1] * k;
                        }
                        let it = &mut self.items[s];
                        it.size = [nw, nh];
                        it.pos = orig.pos;
                        let fix = anchor - it.to_world(pos2(0.0, 0.0));
                        it.pos[0] += fix.x;
                        it.pos[1] += fix.y;
                    }
                }
                Drag::Rotate => {
                    if let (Some(s), Some(p)) = (self.selected, pointer) {
                        let c = to_screen(self.items[s].center());
                        let start = self.drag_start - c;
                        let now = p - c;
                        let orig = self.drag_item.as_ref().map(|o| o.rot).unwrap_or(0.0);
                        let mut a = orig + (now.angle() - start.angle()).to_degrees();
                        if ui.input(|i| i.modifiers.shift) {
                            a = (a / 15.0).round() * 15.0;
                        }
                        self.items[s].rot = a;
                    }
                }
                Drag::None => {}
            }
        }
        if resp.drag_stopped() {
            self.drag = Drag::None;
            self.drag_item = None;
        }

        // zoom buttons in the bottom-left corner
        let zr = Rect::from_min_size(rect.left_bottom() + vec2(14.0, -44.0), vec2(170.0, 32.0));
        let mut zui = ui.new_child(egui::UiBuilder::new().max_rect(zr));
        zui.horizontal(|ui| {
            if ui.button(" - ").clicked() {
                self.zoom = (self.zoom / 1.2).max(0.25);
            }
            ui.label(RichText::new(format!("{:.0}%", self.zoom * 100.0)).color(TEXT));
            if ui.button(" + ").clicked() {
                self.zoom = (self.zoom * 1.2).min(6.0);
            }
        });
    }

    fn make_screen(&mut self, ui: &mut Ui) {
        let mats = self.build_mats();
        if self.mat_index >= mats.len() {
            self.mat_index = 0;
        }

        egui::Panel::left("mats")
            .exact_size(200.0)
            .resizable(false)
            .frame(egui::Frame::NONE.fill(PANEL).stroke(Stroke::new(1.0, LINE)).inner_margin(12))
            .show(ui, |ui| {
                ui.label(RichText::new(format!("{} mat(s)", mats.len())).size(15.0).strong().color(TEXT));
                ui.add_space(6.0);
                egui::ScrollArea::vertical().show(ui, |ui| {
                    for (n, m) in mats.iter().enumerate() {
                        let (r, resp) = ui.allocate_exact_size(vec2(170.0, 150.0), Sense::click());
                        let sel = n == self.mat_index;
                        ui.painter().rect_filled(r, 8.0, if sel { Color32::from_rgb(0xe6, 0xf4, 0xec) } else { PANEL });
                        if sel {
                            ui.painter().rect_stroke(r, 8.0, Stroke::new(2.0, ACCENT), StrokeKind::Inside);
                        }
                        let ms = self.mat_size();
                        let k = 110.0 / ms.y.max(ms.x);
                        let mr = Rect::from_center_size(r.center() - vec2(0.0, 10.0), ms * k);
                        ui.painter().rect_filled(mr, 2.0, Color32::from_rgb(0xb4, 0xd8, 0xf0));
                        let to_s = |p: Pos2| mr.min + p.to_vec2() * k;
                        for (i, off) in &m.pieces {
                            draw_item(ui.painter(), &self.items[*i], &to_s, *off, None);
                        }
                        ui.painter().circle_filled(r.left_bottom() + vec2(16.0, -14.0), 6.0, m.color);
                        ui.painter().text(
                            r.left_bottom() + vec2(28.0, -14.0),
                            Align2::LEFT_CENTER,
                            format!("Mat {}", n + 1),
                            FontId::proportional(12.0),
                            TEXT,
                        );
                        if resp.clicked() {
                            self.mat_index = n;
                        }
                    }
                });
            });

        egui::Panel::bottom("material")
            .exact_size(122.0)
            .frame(egui::Frame::NONE.fill(PANEL).stroke(Stroke::new(1.0, LINE)).inner_margin(14))
            .show(ui, |ui| {
                ui.horizontal(|ui| {
                    ui.vertical(|ui| {
                        ui.label(RichText::new("Material").size(15.0).strong().color(TEXT));
                        egui::ComboBox::from_id_salt("material")
                            .selected_text(MATERIALS[self.material].name)
                            .width(220.0)
                            .show_ui(ui, |ui| {
                                for (i, m) in MATERIALS.iter().enumerate() {
                                    ui.selectable_value(&mut self.material, i, m.name);
                                }
                            });
                        let m = &MATERIALS[self.material];
                        ui.label(
                            RichText::new(format!("Load: {} | pressure {} of 7 | {} pass(es)", m.tool.label(), m.pressure, m.passes))
                                .color(MUTED),
                        );
                    });
                    ui.separator();
                    ui.vertical(|ui| {
                        ui.label(RichText::new("Mat").size(15.0).strong().color(TEXT));
                        ui.horizontal(|ui| {
                            ui.selectable_value(&mut self.mat_long, false, "12 x 12 in");
                            ui.selectable_value(&mut self.mat_long, true, "12 x 24 in");
                        });
                        ui.checkbox(&mut self.mirror, "Mirror (for iron-on)");
                    });
                    ui.separator();
                    ui.vertical(|ui| {
                        ui.label(RichText::new("Send").size(15.0).strong().color(TEXT));
                        ui.horizontal(|ui| {
                            if ui.button("Save mats as SVG").clicked() {
                                let dir = documents_dir();
                                let _ = std::fs::create_dir_all(&dir);
                                let mut saved = 0;
                                for (n, m) in mats.iter().enumerate() {
                                    let p = dir.join(format!("{}-mat{}.svg", self.project_name.replace(['/', '\\'], "_"), n + 1));
                                    if std::fs::write(&p, self.mat_svg(m)).is_ok() {
                                        saved += 1;
                                    }
                                }
                                self.status = format!("Saved {saved} mat file(s) to {}", dir.display());
                            }
                            let go = ui.add_enabled(
                                self.connected.is_some() && !mats.is_empty(),
                                egui::Button::new(RichText::new("Go").color(Color32::WHITE).strong())
                                    .fill(ACCENT)
                                    .corner_radius(CornerRadius::same(16))
                                    .min_size(vec2(80.0, 32.0)),
                            );
                            if go.clicked() {
                                self.log.push(
                                    "Go: wake the machine, clear errors and home the blade. Streaming the cut paths \
                                     themselves is not decoded yet."
                                        .into(),
                                );
                                self.send(Cmd::SendZeros);
                                self.send(Cmd::ClearError);
                                self.send(Cmd::HomeTheta);
                                self.show_machine = true;
                            }
                        });
                        let note = if !self.status.is_empty() {
                            self.status.clone()
                        } else if self.connected.is_none() {
                            "Connect your machine to enable Go.".to_string()
                        } else {
                            "Ready.".to_string()
                        };
                        ui.label(RichText::new(note).color(MUTED));
                    });
                });
            });

        egui::CentralPanel::no_frame().frame(egui::Frame::NONE.fill(CANVAS_BG).inner_margin(20)).show(ui, |ui| {
            let avail = ui.available_rect_before_wrap();
            let ms = self.mat_size();
            let k = ((avail.height() - 40.0) / (ms.y + 1.0)).min((avail.width() - 40.0) / (ms.x + 1.0)).max(4.0);
            let mat_rect = Rect::from_center_size(avail.center(), (ms + vec2(1.0, 1.0)) * k);
            let p = ui.painter();
            p.rect_filled(mat_rect, 6.0, Color32::from_rgb(0x8f, 0xc3, 0xe6));
            let sticky = Rect::from_min_size(mat_rect.min + vec2(0.5, 0.5) * k, ms * k);
            p.rect_filled(sticky, 0.0, Color32::from_rgb(0xb4, 0xd8, 0xf0));
            let grid = Stroke::new(1.0, Color32::from_rgba_unmultiplied(255, 255, 255, 140));
            for i in 0..=(ms.x as i32) {
                let x = sticky.left() + i as f32 * k;
                p.line_segment([pos2(x, sticky.top()), pos2(x, sticky.bottom())], grid);
                if i < ms.x as i32 {
                    p.text(pos2(x + k / 2.0, mat_rect.top() + k * 0.25), Align2::CENTER_CENTER, format!("{}", i + 1), FontId::proportional(10.0), Color32::WHITE);
                }
            }
            for j in 0..=(ms.y as i32) {
                let y = sticky.top() + j as f32 * k;
                p.line_segment([pos2(sticky.left(), y), pos2(sticky.right(), y)], grid);
                if j < ms.y as i32 {
                    p.text(pos2(mat_rect.left() + k * 0.25, y + k / 2.0), Align2::CENTER_CENTER, format!("{}", j + 1), FontId::proportional(10.0), Color32::WHITE);
                }
            }
            match mats.get(self.mat_index) {
                Some(m) => {
                    let to_s = |q: Pos2| sticky.min + q.to_vec2() * k;
                    let mirror = if self.mirror { Some(ms.x) } else { None };
                    for (i, off) in &m.pieces {
                        draw_item(p, &self.items[*i], &to_s, *off, mirror);
                    }
                    if m.overflow {
                        p.text(
                            mat_rect.center_bottom() + vec2(0.0, 12.0),
                            Align2::CENTER_CENTER,
                            "Some pieces don't fit on this mat. Try the 12 x 24 in mat or make them smaller.",
                            FontId::proportional(13.0),
                            Color32::from_rgb(0xc0, 0x39, 0x2b),
                        );
                    }
                }
                None => {
                    p.text(mat_rect.center(), Align2::CENTER_CENTER, "Nothing to cut yet", FontId::proportional(18.0), Color32::WHITE);
                }
            }
        });
    }

    fn machine_window(&mut self, ctx: &egui::Context) {
        let mut open = self.show_machine;
        egui::Window::new("Machine")
            .open(&mut open)
            .default_width(460.0)
            .default_pos(ctx.content_rect().right_top() + vec2(-500.0, 70.0))
            .show(ctx, |ui| {
                ui.label(RichText::new("Connect to your cutting machine over Bluetooth.").color(MUTED));
                ui.horizontal(|ui| {
                    ui.selectable_value(&mut self.settings.link, LinkKind::Bluetooth, "Bluetooth (Linux)");
                    ui.selectable_value(&mut self.settings.link, LinkKind::Device, "Serial device");
                    ui.selectable_value(&mut self.settings.link, LinkKind::Demo, "Demo machine");
                });
                match self.settings.link {
                    LinkKind::Bluetooth => {
                        egui::Grid::new("bt").num_columns(2).show(ui, |ui| {
                            ui.label("Machine address");
                            ui.text_edit_singleline(&mut self.settings.mac);
                            ui.end_row();
                            ui.label("Channel");
                            ui.add(egui::DragValue::new(&mut self.settings.channel).range(1..=30));
                            ui.end_row();
                        });
                        ui.label(
                            RichText::new(format!(
                                "First time on Bazzite: turn the machine on, then in a terminal run\n  bluetoothctl pair {m}\n  bluetoothctl trust {m}",
                                m = self.settings.mac
                            ))
                            .monospace()
                            .size(11.0)
                            .color(MUTED),
                        );
                        #[cfg(target_os = "linux")]
                        if ui.button("Pair and trust now").clicked() {
                            for verb in ["pair", "trust"] {
                                let out = std::process::Command::new("bluetoothctl")
                                    .args(["--timeout", "20", verb, &self.settings.mac])
                                    .output();
                                self.log.push(match out {
                                    Ok(o) => format!(
                                        "bluetoothctl {verb}: {}",
                                        String::from_utf8_lossy(&o.stdout).lines().last().unwrap_or("done")
                                    ),
                                    Err(e) => format!("Couldn't run bluetoothctl: {e}"),
                                });
                            }
                        }
                    }
                    LinkKind::Device => {
                        ui.horizontal(|ui| {
                            ui.label("Device");
                            ui.text_edit_singleline(&mut self.settings.device_path);
                        });
                        ui.label(
                            RichText::new(format!(
                                "On Linux: sudo rfcomm bind 0 {} {}  (then use /dev/rfcomm0)",
                                self.settings.mac, self.settings.channel
                            ))
                            .monospace()
                            .size(11.0)
                            .color(MUTED),
                        );
                    }
                    LinkKind::Demo => {
                        ui.label(RichText::new("A pretend machine that answers every command, to try the app.").color(MUTED));
                    }
                }
                ui.collapsing("Encryption", |ui| {
                    ui.label(
                        RichText::new(
                            "The machine can switch to encrypted messages (AES-256). If yours does, paste the \
                             64-character session key here; leave it empty to talk unencrypted.",
                        )
                        .color(MUTED),
                    );
                    ui.add(egui::TextEdit::singleline(&mut self.settings.key_hex).password(true).desired_width(f32::INFINITY));
                });
                ui.horizontal(|ui| {
                    if self.connected.is_some() {
                        if ui.button("Disconnect").clicked() {
                            let _ = self.machine.tx.send(Request::Disconnect);
                        }
                    } else if green_button(ui, "Connect").clicked() {
                        self.connect();
                    }
                    if let Some((cmd, st)) = self.last_status {
                        ui.label(
                            RichText::new(format!(
                                "Last reply: {} -> status {}",
                                cmd.label(),
                                st.map(|s| s.to_string()).unwrap_or_else(|| "-".into())
                            ))
                            .color(MUTED),
                        );
                    }
                });
                ui.separator();
                ui.add_enabled_ui(self.connected.is_some(), |ui| {
                    ui.horizontal_wrapped(|ui| {
                        for cmd in [
                            Cmd::SendZeros,
                            Cmd::GetInterfaceState,
                            Cmd::ReadErrorSeverity,
                            Cmd::ClearError,
                            Cmd::HomeTheta,
                            Cmd::ScanForEdge,
                            Cmd::GetPersistentValueCount,
                            Cmd::AbortCutting,
                        ] {
                            if ui.button(cmd.label()).clicked() {
                                self.send(cmd);
                            }
                        }
                    });
                    ui.horizontal(|ui| {
                        ui.add(egui::DragValue::new(&mut self.theta).range(-360.0..=360.0).suffix(" deg"));
                        if ui.button(Cmd::Move4D.label()).clicked() {
                            self.send(Cmd::Move4D);
                        }
                    });
                });
                ui.separator();
                egui::ScrollArea::vertical().max_height(180.0).stick_to_bottom(true).show(ui, |ui| {
                    for l in &self.log {
                        ui.label(RichText::new(l).monospace().size(11.0));
                    }
                });
            });
        if !open {
            self.show_machine = false;
        }
    }
}

input.content:
//! The window: a design canvas, a "Make it" screen with mats and materials, and the machine panel.

use crate::geometry::{self, Contour, Operation, ShapeKind};
use crate::machine::{self, Cmd, Event, Link, MachineHandle, Request};
use crate::materials::MATERIALS;
use egui::{
    pos2, vec2, Align, Align2, Color32, CornerRadius, FontId, Key, Layout, Mesh, Pos2, Rect, RichText, Sense,
    Shape, Stroke, StrokeKind, Ui, Vec2,
};

// ---------------------------------------------------------------- look

const HEADER: Color32 = Color32::from_rgb(0x22, 0x2c, 0x33);
const ACCENT: Color32 = Color32::from_rgb(0x16, 0x9c, 0x5c);
const ACCENT_DARK: Color32 = Color32::from_rgb(0x10, 0x7a, 0x47);
const CANVAS_BG: Color32 = Color32::from_rgb(0xf1, 0xf2, 0xf4);
const PANEL: Color32 = Color32::WHITE;
const LINE: Color32 = Color32::from_rgb(0xdd, 0xe1, 0xe5);
const TEXT: Color32 = Color32::from_rgb(0x2a, 0x33, 0x3a);
const MUTED: Color32 = Color32::from_rgb(0x74, 0x7e, 0x87);
const SELECT: Color32 = Color32::from_rgb(0x2f, 0x80, 0xed);

const PALETTE: [Color32; 8] = [
    Color32::from_rgb(0xe8, 0x5d, 0x75),
    Color32::from_rgb(0x3d, 0x8b, 0xd9),
    Color32::from_rgb(0xf2, 0xb1, 0x34),
    Color32::from_rgb(0x2f, 0xa8, 0x6b),
    Color32::from_rgb(0x8e, 0x5c, 0xd6),
    Color32::from_rgb(0x2b, 0x2b, 0x2b),
    Color32::from_rgb(0xf0, 0x7b, 0x3f),
    Color32::from_rgb(0x4a, 0xc1, 0xc8),
];

/// Space kept between pieces and from the mat's edge, in inches.
const MAT_GAP: f32 = 0.25;
/// Screen pixels per design inch at 100 % zoom.
const BASE_PPI: f32 = 48.0;

// ---------------------------------------------------------------- model

#[derive(Clone, serde::Serialize, serde::Deserialize)]
pub struct Item {
    pub name: String,
    #[serde(with = "contours_serde")]
    pub unit: Vec<Contour>,
    pub pos: [f32; 2],
    pub size: [f32; 2],
    pub rot: f32,
    pub color: [u8; 3],
    pub op: Operation,
    pub visible: bool,
    pub text: Option<String>,
}

mod contours_serde {
    use super::Contour;
    use serde::{Deserialize, Deserializer, Serialize, Serializer};
    pub fn serialize<S: Serializer>(c: &[Contour], s: S) -> Result<S::Ok, S::Error> {
        let v: Vec<Vec<[f32; 2]>> = c.iter().map(|c| c.iter().map(|p| [p.x, p.y]).collect()).collect();
        v.serialize(s)
    }
    pub fn deserialize<'de, D: Deserializer<'de>>(d: D) -> Result<Vec<Contour>, D::Error> {
        let v: Vec<Vec<[f32; 2]>> = Vec::deserialize(d)?;
        Ok(v.into_iter().map(|c| c.into_iter().map(|p| egui::pos2(p[0], p[1])).collect()).collect())
    }
}

impl Item {
    fn new(name: &str, unit: Vec<Contour>, pos: Pos2, size: Vec2, color: Color32) -> Self {
        Self {
            name: name.into(),
            unit,
            pos: [pos.x, pos.y],
            size: [size.x, size.y],
            rot: 0.0,
            color: [color.r(), color.g(), color.b()],
            op: Operation::Cut,
            visible: true,
            text: None,
        }
    }
    fn color32(&self) -> Color32 {
        Color32::from_rgb(self.color[0], self.color[1], self.color[2])
    }
    fn center(&self) -> Pos2 {
        pos2(self.pos[0] + self.size[0] / 2.0, self.pos[1] + self.size[1] / 2.0)
    }
    /// Unit-box point to design inches (scale, then rotate around the centre).
    fn to_world(&self, u: Pos2) -> Pos2 {
        let c = self.center();
        let p = vec2((u.x - 0.5) * self.size[0], (u.y - 0.5) * self.size[1]);
        let (s, co) = self.rot.to_radians().sin_cos();
        c + vec2(p.x * co - p.y * s, p.x * s + p.y * co)
    }
    fn from_world(&self, w: Pos2) -> Pos2 {
        let c = self.center();
        let d = w - c;
        let (s, co) = (-self.rot).to_radians().sin_cos();
        let p = vec2(d.x * co - d.y * s, d.x * s + d.y * co);
        pos2(p.x / self.size[0].max(1e-4) + 0.5, p.y / self.size[1].max(1e-4) + 0.5)
    }
    pub fn world_contours(&self) -> Vec<Contour> {
        self.unit.iter().map(|c| c.iter().map(|p| self.to_world(*p)).collect()).collect()
    }
    fn world_bounds(&self) -> Rect {
        let (a, b) = geometry::bounds(self.world_contours().into_iter().flatten());
        Rect::from_min_max(a, b)
    }
}

#[derive(Clone, Copy, PartialEq)]
enum Screen {
    Design,
    Make,
}

#[derive(Clone, Copy, PartialEq)]
enum Drawer {
    None,
    Shapes,
    Text,
    Upload,
    Projects,
}

#[derive(Clone, Copy, PartialEq)]
enum Drag {
    None,
    Move,
    Resize,
    Rotate,
    Pan,
}

#[derive(Clone, Copy, PartialEq, serde::Serialize, serde::Deserialize)]
enum LinkKind {
    Bluetooth,
    Device,
    Demo,
}

#[derive(Clone, serde::Serialize, serde::Deserialize)]
struct MachineSettings {
    link: LinkKind,
    mac: String,
    channel: u8,
    device_path: String,
    key_hex: String,
}

impl Default for MachineSettings {
    fn default() -> Self {
        Self {
            link: if cfg!(target_os = "linux") { LinkKind::Bluetooth } else { LinkKind::Demo },
            mac: machine::DEFAULT_MAC.into(),
            channel: 1,
            device_path: if cfg!(windows) { r"\\.\COM5".into() } else { "/dev/rfcomm0".into() },
            key_hex: String::new(),
        }
    }
}

fn config_dir() -> std::path::PathBuf {
    if let Ok(x) = std::env::var("XDG_CONFIG_HOME") {
        return std::path::PathBuf::from(x).join("matcraft");
    }
    if let Ok(a) = std::env::var("APPDATA") {
        return std::path::PathBuf::from(a).join("matcraft");
    }
    let home = std::env::var("HOME").unwrap_or_else(|_| ".".into());
    std::path::PathBuf::from(home).join(".config").join("matcraft")
}

fn documents_dir() -> std::path::PathBuf {
    let home = std::env::var("HOME").or_else(|_| std::env::var("USERPROFILE")).unwrap_or_else(|_| ".".into());
    std::path::PathBuf::from(home).join("Documents").join("MatCraft")
}

/// A mat to send: its colour and the pieces placed on it (offset from design inches to mat inches).
struct Mat {
    color: Color32,
    pieces: Vec<(usize, Vec2)>,
    overflow: bool,
}

pub struct App {
    screen: Screen,
    drawer: Drawer,
    items: Vec<Item>,
    selected: Option<usize>,
    undo: Vec<Vec<Item>>,
    redo: Vec<Vec<Item>>,
    zoom: f32,
    pan: Vec2,
    drag: Drag,
    drag_start: Pos2,
    drag_item: Option<Item>,
    edit_snapshot_taken: bool,
    lock_aspect: bool,
    text_input: String,
    svg_input: String,
    project_path: String,
    status: String,
    project_name: String,
    // Make it
    mat_long: bool,
    mat_index: usize,
    material: usize,
    mirror: bool,
    // Machine
    machine: MachineHandle,
    settings: MachineSettings,
    connected: Option<String>,
    log: Vec<String>,
    show_machine: bool,
    theta: f32,
    last_status: Option<(Cmd, Option<u8>)>,
}

impl App {
    pub fn new(cc: &eframe::CreationContext<'_>) -> Self {
        cc.egui_ctx.set_visuals(egui::Visuals::light());
        cc.egui_ctx.all_styles_mut(|style| {
            style.visuals.panel_fill = PANEL;
            style.visuals.selection.bg_fill = SELECT;
            style.spacing.item_spacing = vec2(8.0, 6.0);
            style.spacing.button_padding = vec2(10.0, 5.0);
        });

        let settings = std::fs::read_to_string(config_dir().join("machine.json"))
            .ok()
            .and_then(|s| serde_json::from_str(&s).ok())
            .unwrap_or_default();

        let mut app = Self {
            screen: Screen::Design,
            drawer: Drawer::Shapes,
            items: Vec::new(),
            selected: None,
            undo: Vec::new(),
            redo: Vec::new(),
            zoom: 1.0,
            pan: vec2(40.0, 30.0),
            drag: Drag::None,
            drag_start: Pos2::ZERO,
            drag_item: None,
            edit_snapshot_taken: false,
            lock_aspect: true,
            text_input: "Hello".into(),
            svg_input: String::new(),
            project_path: documents_dir().join("project.matcraft.json").display().to_string(),
            status: String::new(),
            project_name: "Untitled project".into(),
            mat_long: false,
            mat_index: 0,
            material: 1,
            mirror: false,
            machine: machine::spawn(cc.egui_ctx.clone()),
            settings,
            connected: None,
            log: Vec::new(),
            show_machine: false,
            theta: 90.0,
            last_status: None,
        };
        app.add_sample();
        app.selected = Some(1);
        app
    }

    fn add_sample(&mut self) {
        let heart = Item::new("Heart", ShapeKind::Heart.unit_contours(), pos2(1.0, 1.0), vec2(3.0, 2.7), PALETTE[0]);
        let mut star = Item::new("Star", ShapeKind::Star.unit_contours(), pos2(4.8, 1.2), vec2(2.6, 2.5), PALETTE[2]);
        star.rot = 8.0;
        self.items.push(heart);
        self.items.push(star);
        self.add_text_item("Hello", pos2(1.2, 4.6), PALETTE[1]);
    }

    fn snapshot(&mut self) {
        self.undo.push(self.items.clone());
        if self.undo.len() > 100 {
            self.undo.remove(0);
        }
        self.redo.clear();
    }

    fn undo(&mut self) {
        if let Some(prev) = self.undo.pop() {
            self.redo.push(std::mem::replace(&mut self.items, prev));
            self.selected = None;
        }
    }

    fn redo(&mut self) {
        if let Some(next) = self.redo.pop() {
            self.undo.push(std::mem::replace(&mut self.items, next));
            self.selected = None;
        }
    }

    fn delete_selected(&mut self) {
        if let Some(s) = self.selected.take().filter(|s| *s < self.items.len()) {
            self.snapshot();
            self.items.remove(s);
        }
    }

    fn duplicate_selected(&mut self) {
        if let Some(s) = self.selected.filter(|s| *s < self.items.len()) {
            self.snapshot();
            let mut c = self.items[s].clone();
            c.pos[0] += 0.5;
            c.pos[1] += 0.5;
            self.items.push(c);
            self.selected = Some(self.items.len() - 1);
        }
    }

    fn next_color(&self) -> Color32 {
        PALETTE[self.items.len() % PALETTE.len()]
    }

    fn add_shape(&mut self, kind: ShapeKind) {
        self.snapshot();
        let size = if kind == ShapeKind::Line { vec2(3.0, 0.0001) } else { vec2(2.0, 2.0) };
        let mut it = Item::new(kind.label(), kind.unit_contours(), pos2(2.0, 2.0), size, self.next_color());
        if kind == ShapeKind::Line {
            it.op = Operation::Score;
            it.color = [0x55, 0x55, 0x55];
        }
        self.items.push(it);
        self.selected = Some(self.items.len() - 1);
    }

    fn add_text_item(&mut self, text: &str, at: Pos2, color: Color32) {
        let contours = geometry::text_contours(text);
        if contours.is_empty() {
            self.status = "That text has no letters the built-in typeface can draw.".into();
            return;
        }
        let (unit, natural) = geometry::normalise(&contours);
        let h = 1.0;
        let size = vec2(natural.x / natural.y.max(1e-4) * h, h);
        let mut it = Item::new(&format!("Text: {}", text.lines().next().unwrap_or("")), unit, at, size, color);
        it.text = Some(text.into());
        self.items.push(it);
        self.selected = Some(self.items.len() - 1);
    }

    fn import_svg(&mut self, text: &str) {
        let contours = geometry::parse_svg(text);
        if contours.is_empty() {
            self.status = "No shapes found in that SVG.".into();
            return;
        }
        self.snapshot();
        let (unit, natural) = geometry::normalise(&contours);
        // Fit the longest side to 4 inches.
        let s = 4.0 / natural.x.max(natural.y).max(1e-4);
        let it = Item::new("Uploaded image", unit, pos2(1.5, 1.5), natural * s, self.next_color());
        self.items.push(it);
        self.selected = Some(self.items.len() - 1);
        self.status = format!("Imported {} outline(s).", contours.len());
    }

    fn save_settings(&self) {
        let dir = config_dir();
        let _ = std::fs::create_dir_all(&dir);
        if let Ok(s) = serde_json::to_string_pretty(&self.settings) {
            let _ = std::fs::write(dir.join("machine.json"), s);
        }
    }

    fn mat_size(&self) -> Vec2 {
        if self.mat_long {
            vec2(12.0, 24.0)
        } else {
            vec2(12.0, 12.0)
        }
    }

    /// Group visible pieces into mats by colour and lay them out in rows from the top-left corner.
    fn build_mats(&self) -> Vec<Mat> {
        let mut colors: Vec<Color32> = Vec::new();
        for it in self.items.iter().filter(|i| i.visible && i.op == Operation::Cut) {
            if !colors.contains(&it.color32()) {
                colors.push(it.color32());
            }
        }
        let size = self.mat_size();
        let mut mats: Vec<Mat> = Vec::new();
        for c in colors {
            let ids: Vec<usize> = (0..self.items.len())
                .filter(|&i| self.items[i].visible && self.items[i].op == Operation::Cut && self.items[i].color32() == c)
                .collect();
            let mut mat = Mat { color: c, pieces: Vec::new(), overflow: false };
            let (mut x, mut y, mut row_h) = (MAT_GAP, MAT_GAP, 0.0f32);
            for i in ids {
                let b = self.items[i].world_bounds();
                if x + b.width() > size.x - MAT_GAP && x > MAT_GAP {
                    x = MAT_GAP;
                    y += row_h + MAT_GAP;
                    row_h = 0.0;
                }
                if y + b.height() > size.y - MAT_GAP || b.width() > size.x - 2.0 * MAT_GAP {
                    mat.overflow = true;
                }
                mat.pieces.push((i, vec2(x, y) - b.min.to_vec2()));
                x += b.width() + MAT_GAP;
                row_h = row_h.max(b.height());
            }
            mats.push(mat);
        }
        // Draw / score / engrave lines go on the first mat, where they sit in the design.
        let extras: Vec<usize> =
            (0..self.items.len()).filter(|&i| self.items[i].visible && self.items[i].op != Operation::Cut).collect();
        if !extras.is_empty() {
            if mats.is_empty() {
                mats.push(Mat { color: Color32::from_gray(200), pieces: Vec::new(), overflow: false });
            }
            for i in extras {
                mats[0].pieces.push((i, Vec2::ZERO));
            }
        }
        mats
    }

    /// The paths of one mat in millimetres, as SVG path data: the same form the original hands its
    /// machine process (one path_data per mat).
    fn mat_svg(&self, mat: &Mat) -> String {
        let size = self.mat_size();
        let mut s = format!(
            "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"{w}mm\" height=\"{h}mm\" viewBox=\"0 0 {w} {h}\">\n",
            w = size.x * 25.4,
            h = size.y * 25.4
        );
        for (i, off) in &mat.pieces {
            let it = &self.items[*i];
            let c = it.color32();
            for mut contour in it.world_contours() {
                for p in contour.iter_mut() {
                    *p += *off;
                    if self.mirror {
                        p.x = size.x - p.x;
                    }
                }
                s.push_str(&format!(
                    "  <path data-op=\"{}\" fill=\"none\" stroke=\"#{:02x}{:02x}{:02x}\" stroke-width=\"0.2\" d=\"{}\"/>\n",
                    it.op.label().to_lowercase(),
                    c.r(),
                    c.g(),
                    c.b(),
                    geometry::contour_to_d(&contour, 25.4)
                ));
            }
        }
        s.push_str("</svg>\n");
        s
    }

    fn pump_machine(&mut self) {
        while let Ok(ev) = self.machine.rx.try_recv() {
            match ev {
                Event::Log(s) => self.log.push(s),
                Event::Connected(n) => {
                    self.log.push(format!("Connected to {n}."));
                    self.connected = Some(n);
                }
                Event::Disconnected(why) => {
                    self.log.push(why);
                    self.connected = None;
                }
                Event::Reply { cmd, status, .. } => self.last_status = Some((cmd, status)),
            }
        }
        if self.log.len() > 400 {
            let n = self.log.len() - 400;
            self.log.drain(..n);
        }
    }

    fn connect(&mut self) {
        let link = match self.settings.link {
            LinkKind::Bluetooth => Link::Rfcomm { mac: self.settings.mac.clone(), channel: self.settings.channel },
            LinkKind::Device => Link::Device { path: self.settings.device_path.clone() },
            LinkKind::Demo => Link::Demo,
        };
        let key = machine::parse_key(&self.settings.key_hex);
        if !self.settings.key_hex.trim().is_empty() && key.is_none() {
            self.log.push("The session key should be 64 hex characters; sending unencrypted instead.".into());
        }
        self.save_settings();
        let _ = self.machine.tx.send(Request::Connect { link, key });
    }

    fn send(&mut self, cmd: Cmd) {
        let _ = self.machine.tx.send(Request::Send { cmd, theta: self.theta });
    }
}

// ---------------------------------------------------------------- drawing helpers

/// Fill outlines with the even-odd rule (holes stay open) by scanning rows of the screen.
fn fill_even_odd(painter: &egui::Painter, contours: &[Vec<Pos2>], color: Color32) {
    let (min, max) = geometry::bounds(contours.iter().flatten().copied());
    if max.y - min.y < 0.5 {
        return;
    }
    let mut mesh = Mesh::default();
    let mut y = min.y.floor() + 0.5;
    let mut xs: Vec<f32> = Vec::new();
    while y < max.y {
        xs.clear();
        for c in contours {
            let n = c.len();
            if n < 2 {
                continue;
            }
            for k in 0..n {
                let a = c[k];
                let b = c[(k + 1) % n];
                if (a.y <= y && b.y > y) || (b.y <= y && a.y > y) {
                    xs.push(a.x + (y - a.y) / (b.y - a.y) * (b.x - a.x));
                }
            }
        }
        xs.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
        for pair in xs.chunks(2) {
            if pair.len() == 2 && pair[1] > pair[0] {
                mesh.add_colored_rect(Rect::from_min_max(pos2(pair[0], y - 0.5), pos2(pair[1], y + 0.5)), color);
            }
        }
        y += 1.0;
    }
    painter.add(Shape::mesh(mesh));
}

fn draw_item(painter: &egui::Painter, it: &Item, to_screen: &dyn Fn(Pos2) -> Pos2, offset: Vec2, mirror_w: Option<f32>) {
    let contours: Vec<Vec<Pos2>> = it
        .world_contours()
        .into_iter()
        .map(|c| {
            c.into_iter()
                .map(|p| {
                    let mut q = p + offset;
                    if let Some(w) = mirror_w {
                        q.x = w - q.x;
                    }
                    to_screen(q)
                })
                .collect()
        })
        .collect();
    let color = it.color32();
    match it.op {
        Operation::Cut => {
            fill_even_odd(painter, &contours, color);
            for c in &contours {
                painter.add(Shape::line(c.clone(), Stroke::new(1.0, color.gamma_multiply(0.6))));
            }
        }
        Operation::Draw | Operation::Engrave => {
            for c in &contours {
                painter.add(Shape::line(c.clone(), Stroke::new(1.6, color)));
            }
        }
        Operation::Score => {
            for c in &contours {
                painter.extend(Shape::dashed_line(c, Stroke::new(1.6, color), 6.0, 4.0));
            }
        }
    }
}

/// A small line-drawn icon for the tool bar.
fn draw_icon(p: &egui::Painter, c: Pos2, which: &str, col: Color32) {
    let s = Stroke::new(1.8, col);
    match which {
        "New" => {
            p.line_segment([c - vec2(8.0, 0.0), c + vec2(8.0, 0.0)], s);
            p.line_segment([c - vec2(0.0, 8.0), c + vec2(0.0, 8.0)], s);
        }
        "Shapes" => {
            p.rect_stroke(Rect::from_center_size(c + vec2(-3.0, 2.0), vec2(10.0, 10.0)), 1.0, s, StrokeKind::Middle);
            p.circle_stroke(c + vec2(4.0, -3.0), 5.5, s);
        }
        "Text" => {
            p.line_segment([c + vec2(-7.0, -7.0), c + vec2(7.0, -7.0)], s);
            p.line_segment([c + vec2(0.0, -7.0), c + vec2(0.0, 8.0)], s);
        }
        "Upload" => {
            p.line_segment([c + vec2(0.0, 6.0), c + vec2(0.0, -7.0)], s);
            p.line_segment([c + vec2(-5.0, -2.0), c + vec2(0.0, -7.0)], s);
            p.line_segment([c + vec2(5.0, -2.0), c + vec2(0.0, -7.0)], s);
            p.line_segment([c + vec2(-8.0, 8.0), c + vec2(8.0, 8.0)], s);
        }
        "Projects" => {
            p.rect_stroke(Rect::from_center_size(c + vec2(0.0, 1.0), vec2(16.0, 12.0)), 2.0, s, StrokeKind::Middle);
            p.line_segment([c + vec2(-8.0, -5.0), c + vec2(-2.0, -5.0)], s);
        }
        _ => {
            // Machine: a little cutter
            p.rect_stroke(Rect::from_center_size(c, vec2(18.0, 10.0)), 3.0, s, StrokeKind::Middle);
            p.line_segment([c + vec2(-4.0, 5.0), c + vec2(-4.0, 9.0)], s);
            p.circle_filled(c + vec2(5.0, 0.0), 2.0, col);
        }
    }
}

fn tool_button(ui: &mut Ui, label: &str, active: bool) -> egui::Response {
    let (rect, resp) = ui.allocate_exact_size(vec2(72.0, 62.0), Sense::click());
    let bg = if active {
        Color32::from_rgb(0xe6, 0xf4, 0xec)
    } else if resp.hovered() {
        Color32::from_rgb(0xf3, 0xf5, 0xf7)
    } else {
        PANEL
    };
    ui.painter().rect_filled(rect.shrink(3.0), 8.0, bg);
    let fg = if active { ACCENT_DARK } else { TEXT };
    draw_icon(ui.painter(), rect.center() - vec2(0.0, 9.0), label, fg);
    ui.painter().text(rect.center() + vec2(0.0, 15.0), Align2::CENTER_CENTER, label, FontId::proportional(11.0), fg);
    resp
}

fn green_button(ui: &mut Ui, text: &str) -> egui::Response {
    ui.add(
        egui::Button::new(RichText::new(text).color(Color32::WHITE).strong().size(15.0))
            .fill(ACCENT)
            .corner_radius(CornerRadius::same(18))
            .min_size(vec2(120.0, 34.0)),
    )
}

fn dark_button(ui: &mut Ui, text: &str) -> egui::Response {
    ui.add(
        egui::Button::new(RichText::new(text).color(Color32::WHITE).size(13.0))
            .fill(Color32::from_rgb(0x34, 0x42, 0x4b))
            .corner_radius(CornerRadius::same(14)),
    )
}

// ---------------------------------------------------------------- the app

impl eframe::App for App {
    fn ui(&mut self, ui: &mut Ui, _frame: &mut eframe::Frame) {
        self.pump_machine();
        let ctx = ui.ctx().clone();

        if self.screen == Screen::Design && !ctx.egui_wants_keyboard_input() {
            let (del, undo, redo, dup) = ctx.input(|i| {
                (
                    i.key_pressed(Key::Delete),
                    i.modifiers.command && i.key_pressed(Key::Z) && !i.modifiers.shift,
                    i.modifiers.command && (i.key_pressed(Key::Y) || (i.modifiers.shift && i.key_pressed(Key::Z))),
                    i.modifiers.command && i.key_pressed(Key::D),
                )
            });
            if del {
                self.delete_selected();
            }
            if undo {
                self.undo();
            }
            if redo {
                self.redo();
            }
            if dup {
                self.duplicate_selected();
            }
        }

        self.header(ui);
        match self.screen {
            Screen::Design => {
                self.edit_bar(ui);
                self.left_bar(ui);
                self.layers_panel(ui);
                if self.drawer != Drawer::None {
                    self.drawer_panel(ui);
                }
                egui::CentralPanel::no_frame().frame(egui::Frame::NONE.fill(CANVAS_BG)).show(ui, |ui| self.canvas(ui));
            }
            Screen::Make => self.make_screen(ui),
        }
        if self.show_machine {
            self.machine_window(&ctx);
        }
    }
}

impl App {
    fn header(&mut self, ui: &mut Ui) {
        egui::Panel::top("header")
            .exact_size(54.0)
            .frame(egui::Frame::NONE.fill(HEADER).inner_margin(egui::Margin::symmetric(16, 8)))
            .show(ui, |ui| {
                ui.horizontal_centered(|ui| {
                    let (r, _) = ui.allocate_exact_size(vec2(28.0, 28.0), Sense::hover());
                    ui.painter().circle_filled(r.center(), 13.0, ACCENT);
                    ui.painter().line_segment(
                        [r.center() + vec2(-6.0, 5.0), r.center() + vec2(6.0, -5.0)],
                        Stroke::new(2.5, Color32::WHITE),
                    );
                    ui.label(RichText::new("MatCraft").color(Color32::WHITE).size(18.0).strong());
                    ui.add_space(16.0);
                    let title = match self.screen {
                        Screen::Design => "Canvas",
                        Screen::Make => "Prepare mats",
                    };
                    ui.label(RichText::new(title).color(Color32::from_gray(190)).size(15.0));
                    ui.label(RichText::new("|").color(Color32::from_gray(110)));
                    ui.add(
                        egui::TextEdit::singleline(&mut self.project_name)
                            .desired_width(170.0)
                            .text_color(Color32::WHITE)
                            .background_color(HEADER)
                            .frame(egui::Frame::NONE),
                    );
                    ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                        match self.screen {
                            Screen::Design => {
                                if green_button(ui, "Make it").clicked() {
                                    self.screen = Screen::Make;
                                    self.mat_index = 0;
                                    self.status.clear();
                                }
                            }
                            Screen::Make => {
                                if dark_button(ui, "Back to canvas").clicked() {
                                    self.screen = Screen::Design;
                                }
                            }
                        }
                        ui.add_space(12.0);
                        let (dot, txt) = match &self.connected {
                            Some(n) => (ACCENT, format!("Machine: {n}")),
                            None => (Color32::from_rgb(0xe0, 0x63, 0x63), "Machine: not connected".to_string()),
                        };
                        let resp = dark_button(ui, &format!("   {txt}"));
                        ui.painter().circle_filled(resp.rect.left_center() + vec2(12.0, 0.0), 4.5, dot);
                        if resp.clicked() {
                            self.show_machine = !self.show_machine;
                        }
                    });
                });
            });
    }

    fn left_bar(&mut self, ui: &mut Ui) {
        egui::Panel::left("tools")
            .exact_size(82.0)
            .resizable(false)
            .frame(egui::Frame::NONE.fill(PANEL).stroke(Stroke::new(1.0, LINE)).inner_margin(4))
            .show(ui, |ui| {
                ui.vertical_centered(|ui| {
                    ui.add_space(6.0);
                    let items = [
                        ("New", Drawer::None),
                        ("Shapes", Drawer::Shapes),
                        ("Text", Drawer::Text),
                        ("Upload", Drawer::Upload),
                        ("Projects", Drawer::Projects),
                    ];
                    for (l, d) in items {
                        let active = d != Drawer::None && self.drawer == d;
                        if tool_button(ui, l, active).clicked() {
                            if l == "New" {
                                self.snapshot();
                                self.items.clear();
                                self.selected = None;
                                self.project_name = "Untitled project".into();
                                self.drawer = Drawer::None;
                            } else {
                                self.drawer = if self.drawer == d { Drawer::None } else { d };
                                self.status.clear();
                            }
                        }
                    }
                    ui.add_space(10.0);
                    if tool_button(ui, "Machine", self.show_machine).clicked() {
                        self.show_machine = !self.show_machine;
                    }
                });
            });
    }

    fn drawer_panel(&mut self, ui: &mut Ui) {
        egui::Panel::left("drawer")
            .exact_size(236.0)
            .resizable(false)
            .frame(egui::Frame::NONE.fill(PANEL).stroke(Stroke::new(1.0, LINE)).inner_margin(12))
            .show(ui, |ui| match self.drawer {
                Drawer::Shapes => {
                    ui.label(RichText::new("Shapes").size(16.0).strong().color(TEXT));
                    ui.label(RichText::new("Click a shape to add it to the canvas.").color(MUTED));
                    ui.add_space(6.0);
                    egui::Grid::new("shapes").spacing(vec2(8.0, 8.0)).show(ui, |ui| {
                        for (n, k) in ShapeKind::ALL.iter().enumerate() {
                            let (r, resp) = ui.allocate_exact_size(vec2(98.0, 84.0), Sense::click());
                            let bg = if resp.hovered() { Color32::from_rgb(0xe6, 0xf4, 0xec) } else { CANVAS_BG };
                            ui.painter().rect_filled(r, 8.0, bg);
                            let inner = Rect::from_center_size(r.center() - vec2(0.0, 8.0), vec2(44.0, 44.0));
                            let cs: Vec<Vec<Pos2>> = k
                                .unit_contours()
                                .into_iter()
                                .map(|c| c.into_iter().map(|p| inner.lerp_inside(p.to_vec2())).collect())
                                .collect();
                            if *k == ShapeKind::Line {
                                for c in &cs {
                                    ui.painter().extend(Shape::dashed_line(c, Stroke::new(2.0, TEXT), 5.0, 3.0));
                                }
                            } else {
                                fill_even_odd(ui.painter(), &cs, Color32::from_gray(150));
                            }
                            ui.painter().text(
                                r.center_bottom() - vec2(0.0, 11.0),
                                Align2::CENTER_CENTER,
                                k.label(),
                                FontId::proportional(12.0),
                                TEXT,
                            );
                            if resp.clicked() {
                                self.add_shape(*k);
                            }
                            if n % 2 == 1 {
                                ui.end_row();
                            }
                        }
                    });
                }
                Drawer::Text => {
                    ui.label(RichText::new("Text").size(16.0).strong().color(TEXT));
                    ui.label(RichText::new("Letters become cut outlines.").color(MUTED));
                    ui.add(egui::TextEdit::multiline(&mut self.text_input).desired_rows(3).desired_width(f32::INFINITY));
                    if green_button(ui, "Add text").clicked() {
                        let t = self.text_input.clone();
                        self.snapshot();
                        let c = self.next_color();
                        self.add_text_item(&t, pos2(1.5, 1.5), c);
                    }
                    if !self.status.is_empty() {
                        ui.label(RichText::new(&self.status).color(MUTED));
                    }
                }
                Drawer::Upload => {
                    ui.label(RichText::new("Upload").size(16.0).strong().color(TEXT));
                    ui.label(RichText::new("Type the path of an SVG file, or paste SVG text.").color(MUTED));
                    ui.add(egui::TextEdit::multiline(&mut self.svg_input).desired_rows(6).desired_width(f32::INFINITY));
                    if green_button(ui, "Import").clicked() {
                        let input = self.svg_input.trim().to_string();
                        let text = if input.starts_with('<') {
                            Some(input)
                        } else {
                            match std::fs::read_to_string(input.trim_matches('"')) {
                                Ok(t) => Some(t),
                                Err(e) => {
                                    self.status = format!("Couldn't read that file: {e}");
                                    None
                                }
                            }
                        };
                        if let Some(t) = text {
                            self.import_svg(&t);
                        }
                    }
                    if !self.status.is_empty() {
                        ui.label(RichText::new(&self.status).color(MUTED));
                    }
                }
                Drawer::Projects => {
                    ui.label(RichText::new("Projects").size(16.0).strong().color(TEXT));
                    ui.label(RichText::new("Save or open a project file.").color(MUTED));
                    ui.add(egui::TextEdit::singleline(&mut self.project_path).desired_width(f32::INFINITY));
                    ui.horizontal(|ui| {
                        if ui.button("Save").clicked() {
                            let p = std::path::PathBuf::from(&self.project_path);
                            if let Some(d) = p.parent() {
                                let _ = std::fs::create_dir_all(d);
                            }
                            self.status = match serde_json::to_string(&self.items)
                                .map_err(|e| e.to_string())
                                .and_then(|s| std::fs::write(&p, s).map_err(|e| e.to_string()))
                            {
                                Ok(()) => format!("Saved {}", p.display()),
                                Err(e) => format!("Couldn't save: {e}"),
                            };
                        }
                        if ui.button("Open").clicked() {
                            match std::fs::read_to_string(&self.project_path)
                                .map_err(|e| e.to_string())
                                .and_then(|s| serde_json::from_str::<Vec<Item>>(&s).map_err(|e| e.to_string()))
                            {
                                Ok(items) => {
                                    self.snapshot();
                                    self.items = items;
                                    self.selected = None;
                                    self.status = "Opened.".into();
                                }
                                Err(e) => self.status = format!("Couldn't open: {e}"),
                            }
                        }
                    });
                    if !self.status.is_empty() {
                        ui.label(RichText::new(&self.status).color(MUTED));
                    }
                }
                Drawer::None => {}
            });
    }

    fn edit_bar(&mut self, ui: &mut Ui) {
        egui::Panel::top("editbar")
            .exact_size(46.0)
            .frame(egui::Frame::NONE.fill(PANEL).stroke(Stroke::new(1.0, LINE)).inner_margin(egui::Margin::symmetric(12, 6)))
            .show(ui, |ui| {
                ui.horizontal_centered(|ui| {
                    if ui.add_enabled(!self.undo.is_empty(), egui::Button::new("Undo")).clicked() {
                        self.undo();
                    }
                    if ui.add_enabled(!self.redo.is_empty(), egui::Button::new("Redo")).clicked() {
                        self.redo();
                    }
                    ui.separator();
                    let Some(s) = self.selected.filter(|s| *s < self.items.len()) else {
                        ui.label(RichText::new("Select a shape to change its size, position and operation.").color(MUTED));
                        return;
                    };
                    let before = self.items[s].clone();
                    let lock = self.lock_aspect;
                    let mut toggle_lock = false;
                    {
                        let it = &mut self.items[s];
                        ui.label(RichText::new("Operation").color(MUTED));
                        egui::ComboBox::from_id_salt("op").selected_text(it.op.label()).width(80.0).show_ui(ui, |ui| {
                            for op in Operation::ALL {
                                ui.selectable_value(&mut it.op, op, op.label());
                            }
                        });
                        let mut c = it.color32();
                        if ui.color_edit_button_srgba(&mut c).changed() {
                            it.color = [c.r(), c.g(), c.b()];
                        }
                        ui.separator();
                        ui.label(RichText::new("Size").color(MUTED));
                        let (ow, oh) = (it.size[0], it.size[1]);
                        ui.add(egui::DragValue::new(&mut it.size[0]).speed(0.02).range(0.05..=24.0).prefix("W ").suffix(" in").fixed_decimals(2));
                        if ui.selectable_label(lock, if lock { "Locked" } else { "Unlocked" }).clicked() {
                            toggle_lock = true;
                        }
                        ui.add(egui::DragValue::new(&mut it.size[1]).speed(0.02).range(0.0001..=24.0).prefix("H ").suffix(" in").fixed_decimals(2));
                        if lock && ow > 1e-3 && oh > 1e-3 {
                            if it.size[0] != ow {
                                it.size[1] = oh * it.size[0] / ow;
                            } else if it.size[1] != oh {
                                it.size[0] = ow * it.size[1] / oh;
                            }
                        }
                        ui.separator();
                        ui.label(RichText::new("Rotate").color(MUTED));
                        ui.add(egui::DragValue::new(&mut it.rot).speed(0.5).range(-360.0..=360.0).suffix(" deg").fixed_decimals(0));
                        ui.label(RichText::new("Position").color(MUTED));
                        ui.add(egui::DragValue::new(&mut it.pos[0]).speed(0.02).prefix("X ").fixed_decimals(2));
                        ui.add(egui::DragValue::new(&mut it.pos[1]).speed(0.02).prefix("Y ").fixed_decimals(2));
                        if ui.button("Flip").clicked() {
                            for c in &mut it.unit {
                                for p in c.iter_mut() {
                                    p.x = 1.0 - p.x;
                                }
                            }
                        }
                    }
                    if toggle_lock {
                        self.lock_aspect = !self.lock_aspect;
                    }
                    let it = &self.items[s];
                    let changed = it.size != before.size
                        || it.rot != before.rot
                        || it.pos != before.pos
                        || it.op != before.op
                        || it.color != before.color
                        || it.unit.first().and_then(|c| c.first()) != before.unit.first().and_then(|c| c.first());
                    let editing = ui.ctx().is_using_pointer() || ui.ctx().egui_wants_keyboard_input();
                    if changed && !self.edit_snapshot_taken {
                        let mut snap = self.items.clone();
                        snap[s] = before;
                        self.undo.push(snap);
                        self.redo.clear();
                        self.edit_snapshot_taken = editing;
                    }
                    if !editing {
                        self.edit_snapshot_taken = false;
                    }
                });
            });
    }

