//! A side-by-side of the original design app and this one, from what was read in the original's
//! files (pages in its packed web app, its helper programs, its machine program).

use egui::{Color32, RichText, Ui};

#[derive(Clone, Copy, PartialEq)]
pub enum Status {
    Same,
    Partial,
    Missing,
    Extra,
}

impl Status {
    fn label(self) -> &'static str {
        match self {
            Status::Same => "Same",
            Status::Partial => "Partly",
            Status::Missing => "Not yet",
            Status::Extra => "Only here",
        }
    }
    fn color(self) -> Color32 {
        match self {
            Status::Same => Color32::from_rgb(0x16, 0x9c, 0x5c),
            Status::Partial => Color32::from_rgb(0xd9, 0x8b, 0x10),
            Status::Missing => Color32::from_rgb(0xc8, 0x3c, 0x3c),
            Status::Extra => Color32::from_rgb(0x2f, 0x80, 0xed),
        }
    }
}

pub struct Row {
    pub area: &'static str,
    pub feature: &'static str,
    pub original: &'static str,
    pub here: &'static str,
    pub status: Status,
}

pub const ROWS: &[Row] = &[
    // --- running it
    Row { area: "Running it", feature: "Computers", original: "Windows and macOS (Electron app)", here: "Linux (Bazzite) and Windows, one small program", status: Status::Extra },
    Row { area: "Running it", feature: "Account and sign-in", original: "Sign-in page; needs an online account", here: "No account, works fully offline", status: Status::Extra },
    Row { area: "Running it", feature: "Home page with projects and ideas", original: "Home page with ready-made projects", here: "Opens straight to the canvas", status: Status::Missing },
    Row { area: "Running it", feature: "Several projects in tabs", original: "Tabs page", here: "One project at a time", status: Status::Missing },
    // --- designing
    Row { area: "Designing", feature: "Canvas with grid and rulers", original: "Grid canvas in inches or cm", here: "Grid canvas in inches, zoom and pan", status: Status::Partial },
    Row { area: "Designing", feature: "Basic shapes", original: "Square, circle, triangle, star, heart, hexagon, octagon, score line and more", here: "Square, circle, triangle, star, heart, hexagon, score line", status: Status::Partial },
    Row { area: "Designing", feature: "Text", original: "Many fonts (own library and computer fonts), letter spacing, curve text", here: "One built-in typeface, several lines", status: Status::Partial },
    Row { area: "Designing", feature: "Upload images", original: "SVG, DXF, PNG/JPG with background removal and tracing", here: "SVG files or pasted SVG text", status: Status::Partial },
    Row { area: "Designing", feature: "Image and project library", original: "Large online library (subscription)", here: "None", status: Status::Missing },
    Row { area: "Designing", feature: "Move, resize, rotate, flip", original: "Handles plus exact numbers", here: "Corner handles (delete, rotate, resize, lock) plus exact numbers", status: Status::Same },
    Row { area: "Designing", feature: "Layers panel", original: "Layers with hide, group, colour sync", here: "Layers with hide, duplicate, delete", status: Status::Partial },
    Row { area: "Designing", feature: "Weld, slice, attach, offset, contour", original: "Path tools (separate helper program)", here: "Not yet", status: Status::Missing },
    Row { area: "Designing", feature: "Undo / redo", original: "Yes", here: "Yes (Ctrl+Z, Ctrl+Y), also duplicate (Ctrl+D)", status: Status::Same },
    Row { area: "Designing", feature: "Operations: cut, draw, score, engrave", original: "Cut, draw, pen, score, engrave, deboss, wave, perforate, print then cut", here: "Cut, draw, score, engrave", status: Status::Partial },
    Row { area: "Designing", feature: "Monogram maker", original: "Built-in plugin", here: "Not yet", status: Status::Missing },
    Row { area: "Designing", feature: "Save and open projects", original: "Cloud saves, plus offline saves", here: "Project files on your computer", status: Status::Partial },
    // --- making
    Row { area: "Making", feature: "Mats by colour", original: "One mat per colour, pieces packed automatically", here: "One mat per colour, pieces placed in rows", status: Status::Same },
    Row { area: "Making", feature: "Mat sizes and mirror", original: "12x12, 12x24 and more; mirror for iron-on", here: "12x12 and 12x24; mirror", status: Status::Same },
    Row { area: "Making", feature: "Moving pieces on a mat by hand", original: "Drag pieces, move between mats", here: "Automatic layout only", status: Status::Missing },
    Row { area: "Making", feature: "Material settings", original: "Hundreds of materials downloaded from its service, custom materials", here: "13 common materials, estimated pressures", status: Status::Partial },
    Row { area: "Making", feature: "Print Then Cut", original: "Prints on your printer, then cuts around (helper program)", here: "Not yet", status: Status::Missing },
    Row { area: "Making", feature: "Save mats as files", original: "Not offered", here: "Saves each mat as an SVG in millimetres", status: Status::Extra },
    // --- machine
    Row { area: "Machine", feature: "Bluetooth connection", original: "Bluetooth serial (RFCOMM) through its helper program", here: "Bluetooth serial straight to 00:06:66:8D:2B:FE on Linux, or a serial port, or a demo machine", status: Status::Same },
    Row { area: "Machine", feature: "USB connection", original: "Yes", here: "Only through a serial device path", status: Status::Partial },
    Row { area: "Machine", feature: "Message format", original: "2-byte length header, optional AES-256", here: "Same format, from the decoded program", status: Status::Same },
    Row { area: "Machine", feature: "Status and service commands", original: "Clear error, read buttons, home blade, stop, find edge...", here: "Same 15 command numbers, with a live message log", status: Status::Same },
    Row { area: "Machine", feature: "Encrypted session", original: "Automatic, using keys built into the program", here: "Sends the request; key must be pasted in (built-in keys not copied)", status: Status::Partial },
    Row { area: "Machine", feature: "Actually cutting your design", original: "Yes", here: "Not yet: Go only wakes, clears errors and homes the blade", status: Status::Missing },
    Row { area: "Machine", feature: "Firmware updates, calibration", original: "Yes", here: "No", status: Status::Missing },
];

