}

fn header_button(ui: &mut Ui, text: &str) -> egui::Response {
    ui.add(
        egui::Button::new(RichText::new(text).color(Color32::from_gray(225)).size(13.0))
            .fill(HEADER_2)
            .stroke(Stroke::NONE)
            .corner_radius(CornerRadius::same(16))
