/// Turn text into cut-ready outlines using the built-in typeface. Height of a capital ≈ 1 unit.
pub fn text_contours(text: &str) -> Vec<Contour> {
    let Ok(face) = ttf_parser::Face::parse(epaint_default_fonts::UBUNTU_LIGHT, 0) else {
        return Vec::new();
    };
    let cap = face.capital_height().unwrap_or(700) as f32;
    let scale = 1.0 / cap.max(1.0);
    let mut sink = OutlineSink { contours: Vec::new(), cur: Vec::new(), pen: Pos2::ZERO, origin_x: 0.0, scale };
    let mut line_y = 0.0f32;
    let line_h = face.height() as f32 * scale;
    for line in text.lines() {
        sink.origin_x = 0.0;
        let before = sink.contours.len();
        for ch in line.chars() {
            if let Some(gid) = face.glyph_index(ch) {
                let _ = face.outline_glyph(gid, &mut sink);
                if sink.cur.len() > 1 {
                    let c = std::mem::take(&mut sink.cur);
                    sink.contours.push(c);
                }
                sink.cur.clear();
                sink.origin_x += face.glyph_hor_advance(gid).unwrap_or(500) as f32 * scale;
            } else {
                sink.origin_x += 0.5;
            }
        }
        for c in &mut sink.contours[before..] {
            for p in c.iter_mut() {
                p.y += line_y;
            }
        }
        line_y += line_h;
    }
    sink.contours
}

