    name: String,
    pic: Picture,
    cleanup: Cleanup,
    print: bool,
    width_in: f32,
    mask: Vec<bool>,
    orig_tex: Option<TextureHandle>,
    preview_tex: Option<TextureHandle>,
    dirty: bool,
}

struct OffsetTool {
