egui::Window::new(RichText::new(format!("Upload: {}", imp.name)).strong())
    .open(&mut open)
    .default_width(760.0)
    .default_pos(ctx.content_rect().center() + vec2(-380.0, -300.0))
    .collapsible(false)
    .show(ctx, |ui| {
        ui.horizontal(|ui| {
            ui.label(RichText::new("How should this picture be made?").color(MUTED));
            segmented(ui, &mut imp.print, &[(false, "Cut image (outline only)"), (true, "Print then cut")]);
        });
        ui.add_space(6.0);
        let side = 320.0;
        let aspect = imp.pic.h as f32 / imp.pic.w as f32;
        let size = if aspect > 1.0 { vec2(side / aspect, side) } else { vec2(side, side * aspect) };
        let mut traced_preview: Vec<Contour> = Vec::new();
        if !imp.print {
            traced_preview = imaging::trace(&imp.pic, &imp.mask, imp.cleanup.smooth);
        }
        ui.horizontal(|ui| {
            ui.vertical(|ui| {
                ui.label(RichText::new("Original").size(12.0).color(MUTED));
                if let Some(t) = &imp.orig_tex {
                    ui.add(egui::Image::new(t).fit_to_exact_size(size).corner_radius(8.0));
                }
            });
            ui.vertical(|ui| {
                ui.label(RichText::new(if imp.print { "Printed part" } else { "What will be cut" }).size(12.0).color(MUTED));
                if let Some(t) = &imp.preview_tex {
                    let r = ui.add(egui::Image::new(t).fit_to_exact_size(size).corner_radius(8.0)).rect;
                    let k = r.width() / imp.pic.w as f32;
                    for c in &traced_preview {
                        let pts: Vec<Pos2> = c.iter().map(|p| r.min + p.to_vec2() * k).collect();
                        ui.painter().add(Shape::line(pts, Stroke::new(1.4, DANGER)));
                    }
                }
            });
        });
        ui.add_space(6.0);
        let before = imp.cleanup.clone();
        ui.horizontal(|ui| {
            ui.checkbox(&mut imp.cleanup.remove_background, "Remove the background colour");
            if imp.cleanup.remove_background {
                ui.add(egui::Slider::new(&mut imp.cleanup.tolerance, 5..=200).text("how much"));
            } else {
                ui.add(egui::Slider::new(&mut imp.cleanup.threshold, 10..=250).text("darkness kept"));
            }
        });
        ui.horizontal(|ui| {
            ui.checkbox(&mut imp.cleanup.invert, "Swap kept and removed");
            if !imp.print {
                ui.add(egui::Slider::new(&mut imp.cleanup.smooth, 0.3..=5.0).text("smoothing"));
            }
            ui.label(RichText::new("Width").color(MUTED));
            ui.add(egui::DragValue::new(&mut imp.width_in).speed(0.05).range(0.25..=23.0).suffix(" in"));
        });
        if imp.cleanup != before {
            imp.dirty = true;
        }
        if imp.print {
            ui.label(
                RichText::new(format!(
                    "Prints on your printer, then the machine cuts around it. Largest print size {:.2} x {:.2} in.",
                    PRINT_AREA.x, PRINT_AREA.y
                ))
                .size(12.0)
                .color(MUTED),
            );
        } else {
            ui.label(RichText::new(format!("{} outline(s) will be cut.", traced_preview.len())).size(12.0).color(MUTED));
        }
        ui.add_space(4.0);
        ui.horizontal(|ui| {
            if primary_button(ui, "Add to canvas").clicked() {
                apply = true;
            }
            if secondary_button(ui, "Save as SVG...").on_hover_text("Keep a cut-ready SVG copy of this picture").clicked() {
                save_svg = true;
            }
        });
        if !svg_note.is_empty() {
            ui.label(RichText::new(svg_note.as_str()).size(12.0).color(MUTED));
        }
    });

