    let base = if even_odd { closed.clone() } else { combine(&closed, &[], Combine::Unite) };
    let area = if inset > 0.0 { offset_contours(&base, -inset) } else { base };
    if area.is_empty() {
        return Vec::new();
    }
    if pattern == FillPattern::Concentric {
        let mut out = Vec::new();
        let mut ring = area.clone();
        for _ in 0..2000 {
            if ring.is_empty() {
