            }
            out.extend(ring.iter().cloned());
            ring = offset_contours(&ring, -spacing);
        }
        return out;
    }
    let mut out = Vec::new();
    for &deg in pattern.angles() {
        let (s, c) = (-deg).to_radians().sin_cos();
