        Icon::Plus => {
            p.circle_stroke(c, s * 0.55, st);
            p.add(poly(&[(-0.25, 0.0), (0.25, 0.0)]));
            p.add(poly(&[(0.0, -0.25), (0.0, 0.25)]));
