                                for m in MachineModel::ALL {
                                    ui.selectable_value(&mut self.prefs.model, m, m.label());
                                }
                            });
                        });
                        row(ui, "Load type", &mut |ui| {
                            egui::ComboBox::from_id_salt("load-type").selected_text(self.prefs.load.label()).width(260.0).show_ui(ui, |ui| {
