            self.toggle_dark(ctx);
        }
        if forget_machine {
            self.settings = MachineSettings::default();
            self.save_settings();
            let _ = self.machine.tx.send(Request::Disconnect);
        }
        if !open {
            self.show_settings = false;
        }
        if serde_json::to_string(&self.prefs).unwrap_or_default() != before {
            self.save_prefs();
        }
    }
}

