                            ui.label(RichText::new(label).size(14.5).color(INK()));
                        });
                        add(ui);
                    });
                    ui.add_space(8.0);
                };
                match self.settings_tab {
                    0 => {
                        row(ui, "Language", &mut |ui| {
                            ui.label("English");
