                                ui.label(RichText::new(format!("Address {}", self.settings.mac)).size(12.0).color(MUTED()));
                            });
                            ui.add_space(8.0);
                            ui.horizontal(|ui| {
                                ui.label(RichText::new("Autoconnect").color(INK()));
