pub fn spawn(ctx: egui::Context) -> MachineHandle {
    let (req_tx, req_rx) = channel::<Request>();
    let (ev_tx, ev_rx) = channel::<Event>();
    std::thread::spawn(move || {
        let send = |e: Event| {
            let _ = ev_tx.send(e);
            ctx.request_repaint();
        };
