    /// The machine's USB cable: a USB serial port (COM6 on Windows, /dev/ttyACM0 on Linux).
    /// An empty port means "find it by its USB vendor id".
    Usb { port: String },
    /// A pretend machine inside the app, for trying things without hardware.
    Demo,
