folder = sys.argv[1]
data = json.load(open(folder + '/capture.json', encoding='utf-8'))


def find_html(obj):
    if isinstance(obj, str):
        if '<' in obj and 'entry-content' in obj:
            return obj
        return None
    if isinstance(obj, dict):
        for v in obj.values():
            r = find_html(v)
            if r:
                return r
    if isinstance(obj, list):
        for v in obj:
            r = find_html(v)
            if r:
                return r
    return None


